mapper.select:
select * from ( select distinct m.device_code, m.device_status, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end) as device_name, m.longitude, m.latitude, m.province_id, m.city_id, m.county_id, m.town_code, m.model_code, m.device_type, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_model_type' AND DICT_VALUE = m.device_type limit 1) deviceTypeName, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, m.device_model_code, m.height, m.w_zone, m.device_period, m.par_angle, m.location, m.site_code, pro.area_name as provinceName, city.area_name as cityName, county.area_name as countyName, town.area_name as townName, '1' as prolevel, '2' as citylevel, '3' as countrylevel, '4' as townLevel, '5' as deviceLevel, m.device_code as code, m.device_name as name, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end) as device_alias, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor,
case when IFNULL(art.id,0) = 0 then '0' else '1' end tagCollect,
osd.ord_status as orderStatus from vm_order_sensor_devices osd left join vm_iot_device_t m on m.device_code = osd.device_code and m.category_code = 2 left join sys_area pro on pro.area_code = m.province_id left join sys_area city on city.area_code = m.city_id left join sys_area county on county.area_code = m.county_id left join sys_area town on town.area_code = m.town_code left join vm_tenant_iot_device_rel_t dr on dr.device_code = m.device_code and dr.tenant_id = osd.tenant_id and dr.delete_flag = '0' and dr.industry_code = osd.industry_code
LEFT JOIN vm_organ_device_rel_t vod on vod.device_code = osd.device_code and osd.tenant_id = vod.tenant_id and vod.device_type = 8 and vod.delete_flag = '0'
left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '7' AND dct.user_id = #{param.userId}
LEFT JOIN vm_ar_tags_tree_user_rel art on art.coll_obj_code = m.device_code and art.coll_obj_type = '7' and art.user_id = #{param.userId}
where osd.delete_flag= '0' and m.delete_flag= '0' and osd.category_code = 2 and osd.tenant_id =#{param.tenantId}
and vod.dept_id in
#{id}
and art.coll_obj_code IS NOT NULL
and dct.user_device_coll_id IS NOT NULL
and m.device_status != 2
AND m.province_id = #{param.provinceId}
AND m.city_id = #{param.cityId}
AND m.county_id = #{param.countyId}
AND m.town_code = #{param.townCode}
and m.device_code like CONCAT('%', #{param.deviceCode}, '%')
and m.device_status = #{param.deviceStatus}
and m.device_status in
#{status}
and m.device_type in
#{type}
and m.model_code = #{param.modelCode}
and osd.ord_status in (0, 1, 2)
and osd.ord_status = #{param.orderStatus}
AND exists not exists ( select 1 from vm_tenant_iot_device_conf_t ac where ac.device_code = m.device_code and ac.tenant_id = osd.tenant_id )
${param.dataScope} order by m.province_id, m.city_id, m.county_id,m.device_code ) dt
dt.device_alias like CONCAT('%', #{param.deviceName}, '%')

select * from ( select distinct gg.dept_id as org_id, gg.dept_name as org_name, gg.dept_level as org_level, gg.parent_id as parent_org_id, m.device_code, m.device_status, m.longitude, m.latitude, m.model_code, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, m.device_model_code, m.w_zone, m.device_period, m.par_angle, m.location, m.site_code, concat(gg.dept_level + 1) AS devLevel, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end) as device_name, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor, osd.ord_status as orderStatus from sys_dept gg left join vm_organ_device_rel_t dd on dd.dept_id = gg.dept_id and dd.device_type = 8 and dd.delete_flag = 0 left join vm_order_sensor_devices osd on osd.device_code = dd.device_code and osd.delete_flag = 0 and osd.tenant_id = dd.tenant_id and osd.industry_code = dd.industry_code left join vm_iot_device_t m on osd.device_code = m.device_code and m.category_code = 2 and m.delete_flag = 0 left join vm_tenant_iot_device_rel_t dr on dr.device_code = m.device_code and dr.tenant_id = osd.tenant_id and dr.delete_flag = '0' and dr.industry_code = osd.industry_code left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '7' AND dct.user_id = #{param.userId} where gg.del_flag = 0 and dd.device_code IS NOT NULL and dd.device_code != '' and osd.tenant_id = #{param.tenantId} and osd.category_code = 2 and m.device_status != 2
and dct.user_device_coll_id IS NOT NULL
and m.device_code like CONCAT('%', #{param.deviceCode}, '%')
and m.device_status = #{param.deviceStatus}
and m.device_status in
#{status}
and m.device_type in
#{type}
and m.model_code = #{param.modelCode}
and osd.ord_status in (0, 1, 2)
and osd.ord_status = #{param.orderStatus}
${param.dataScope} order by gg.dept_id,m.device_code ) dt
dt.device_name like CONCAT('%', #{param.deviceName}, '%')

select DISTINCT m.site_code, m.longitude, m.latitude, m.location, m.device_code as deviceCode, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end ) as device_name, m.province_id, m.city_id, m.county_id, m.town_code, m.height, m.device_status, m.model_code, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_model_type' AND DICT_VALUE = m.device_type limit 1) deviceTypeName, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, m.device_model_code, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor from vm_order_sensor_devices osd left join vm_iot_device_t m on osd.device_code = m.device_code and m.category_code = 2 and m.delete_flag = 0 left join vm_tenant_iot_device_rel_t dr on dr.device_code = m.device_code and dr.tenant_id = osd.tenant_id and dr.delete_flag = '0' and dr.industry_code = osd.industry_code left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '7' AND dct.user_id = #{param.userId} where osd.delete_flag = 0 and osd.ord_status in (0,1,2) and osd.category_code = 2 and m.delete_flag= '0' and m.device_status != 2
AND m.province_id = #{param.provinceId}
AND m.city_id = #{param.cityId}
AND m.county_id = #{param.countyId}
AND m.town_code = #{param.townCode}
${param.dataScope} group by m.site_code, m.device_code

select DISTINCT m.site_code, m.longitude, m.latitude, m.location, m.device_code, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end ) as device_name, m.province_id, m.city_id, m.county_id, m.town_code, m.height, m.device_status, m.model_code, m.device_period, m.w_zone, m.par_angle, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_model_type' AND DICT_VALUE = m.device_type limit 1) deviceTypeName, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, m.device_model_code, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor from vm_order_sensor_devices osd left join vm_iot_device_t m on osd.device_code = m.device_code and m.category_code = 2 and m.delete_flag = 0 left join vm_tenant_iot_device_rel_t dr on dr.device_code = m.device_code and dr.tenant_id = osd.tenant_id and dr.delete_flag = '0' and dr.industry_code = osd.industry_code left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '7' AND dct.user_id = #{param.userId} where osd.delete_flag = 0 and osd.ord_status in (0,1,2) and osd.category_code = 2 and m.delete_flag= '0' and m.device_status != 2
AND m.province_id = #{param.provinceId}
AND m.city_id = #{param.cityId}
AND m.county_id = #{param.countyId}
AND m.town_code = #{param.townCode}
and m.device_type in
#{type}
${param.dataScope} group by m.site_code, m.device_code

select distinct m.device_code, m.model_code, m.device_type, m.device_model_code, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end ) as device_name, m.province_id, m.city_id, m.county_id, m.town_code, m.site_code, m.device_status, m.latitude, m.longitude, m.location, m.height, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_model_type' AND DICT_VALUE = m.device_type limit 1) deviceTypeName, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor from vm_order_sensor_devices osd left join vm_iot_device_t m on osd.device_code = m.device_code and m.category_code = 2 and m.delete_flag = 0 left join vm_tenant_iot_device_rel_t dr on dr.device_code = m.device_code and dr.tenant_id = osd.tenant_id and dr.delete_flag = '0' and dr.industry_code = osd.industry_code left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '7' AND dct.user_id = #{param.userId} where osd.delete_flag = 0 and osd.ord_status in (0,1,2) and osd.category_code = 2 and m.delete_flag= '0' and m.device_status != 2
AND m.site_code = #{param.siteCode}
AND m.device_code = #{param.deviceCode}
${param.dataScope}

select distinct m.device_code, m.model_code, m.device_type, m.device_model_code, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end ) as device_name, m.province_id, m.city_id, m.county_id, m.town_code, m.site_code, m.device_status, m.latitude, m.longitude, m.location, m.height, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_model_type' AND DICT_VALUE = m.device_type limit 1) deviceTypeName, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor from vm_order_sensor_devices osd left join vm_iot_device_t m on osd.device_code = m.device_code and m.category_code = 2 and m.delete_flag = 0 left join vm_tenant_iot_device_rel_t dr on dr.device_code = m.device_code and dr.tenant_id = osd.tenant_id and dr.delete_flag = '0' and dr.industry_code = osd.industry_code left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '7' AND dct.user_id = #{param.userId} where osd.delete_flag = 0 and osd.ord_status in (0,1,2) and osd.category_code = 2 and m.delete_flag= '0' and m.device_status != 2
AND m.site_code = #{param.siteCode}
AND m.device_code = #{param.deviceCode}
${param.dataScope}

select DISTINCT m.site_code, m.longitude, m.latitude, m.location, m.device_code as device_code, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end ) as device_name, m.province_id, m.device_type, m.city_id, m.county_id, m.town_code, m.height, m.w_zone, m.device_status, m.model_code, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'radar_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, m.device_model_code, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor from vm_order_sensor_devices osd left join vm_iot_device_t m on osd.device_code = m.device_code and m.category_code = 1 and m.delete_flag = 0 left join vm_tenant_iot_device_rel_t dr on dr.device_code = m.device_code and dr.tenant_id = osd.tenant_id and dr.delete_flag = '0' and dr.industry_code = osd.industry_code left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '8' AND dct.user_id = #{param.userId} where osd.delete_flag = 0 and osd.ord_status in (0,1,2) and osd.category_code = 1 and m.delete_flag= '0' and m.device_status != 2
AND m.province_id = #{param.provinceId}
AND m.city_id = #{param.cityId}
AND m.county_id = #{param.countyId}
AND m.town_code = #{param.townCode}
and m.device_type in
#{type}
${param.dataScope} group by m.site_code, m.device_code

select m.device_code, m.model_code, m.device_model_code, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end ) as device_name, m.province_id, m.city_id, m.county_id, m.town_code, m.site_code, m.device_status, m.latitude, m.longitude, m.location, m.height, m.device_period, m.w_zone, m.par_angle, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'radar_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor from vm_order_sensor_devices osd left join vm_iot_device_t m on osd.device_code = m.device_code and m.category_code = 1 and m.delete_flag = 0 left join vm_tenant_iot_device_rel_t dr on dr.device_code = m.device_code and dr.tenant_id = osd.tenant_id and dr.delete_flag = '0' and dr.industry_code = osd.industry_code left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '8' AND dct.user_id = #{param.userId} where osd.delete_flag = 0 and osd.ord_status in (0,1,2) and osd.category_code = 1 and m.delete_flag= '0' and m.device_status != 2
AND m.site_code = #{param.siteCode}
AND m.device_code = #{param.deviceCode}
${param.dataScope}

select * from ( select distinct gg.dept_id as org_id, gg.dept_name as org_name, gg.dept_level as org_level, gg.parent_id as parent_org_id, m.device_code, m.device_status, m.longitude, m.latitude, m.model_code, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'radar_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, m.device_model_code, m.w_zone, m.device_period, m.par_angle, m.location, m.site_code, concat(gg.dept_level + 1) AS devLevel, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end) as device_name, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor, osd.ord_status as orderStatus from sys_dept gg left join vm_organ_device_rel_t dd on dd.dept_id = gg.dept_id and dd.device_type = 10 and dd.delete_flag = 0 left join vm_order_sensor_devices osd on osd.device_code = dd.device_code and osd.delete_flag = 0 and osd.tenant_id = dd.tenant_id and osd.industry_code = dd.industry_code left join vm_iot_device_t m on osd.device_code = m.device_code and m.category_code = 1 and m.delete_flag = 0 left join vm_tenant_iot_device_rel_t dr on dr.device_code = m.device_code and dr.tenant_id = osd.tenant_id and dr.delete_flag = '0' and dr.industry_code = osd.industry_code left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '8' AND dct.user_id = #{param.userId} where gg.del_flag = 0 and dd.device_code IS NOT NULL and dd.device_code != '' and osd.tenant_id =#{param.tenantId} and osd.category_code = 1 and m.delete_flag= '0' and m.device_status != 2
and dct.user_device_coll_id IS NOT NULL
and m.device_code like CONCAT('%', #{param.deviceCode}, '%')
and m.device_code in
#{item}
and m.device_status = #{param.deviceStatus}
and m.device_status in
#{status}
and m.device_type in
#{type}
and m.model_code = #{param.modelCode}
and osd.ord_status in (0, 1, 2)
and osd.ord_status = #{param.orderStatus}
${param.dataScope} order by gg.dept_id,m.device_code ) dt
dt.device_name like CONCAT('%', #{param.deviceName}, '%')

select * from ( select distinct m.device_code, m.device_status, m.device_name, m.longitude, m.latitude, m.province_id, m.city_id, m.county_id, m.town_code, m.model_code, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'radar_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, m.device_model_code, m.w_zone, m.device_period, m.par_angle, m.location, m.site_code, pro.area_name as provinceName, city.area_name as cityName, county.area_name as countyName, town.area_name as townName, '1' as prolevel, '2' as citylevel, '3' as countrylevel, '4' as townLevel, '5' as deviceLevel, m.device_code as code, m.device_name as name, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end) as device_alias, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor,
case when IFNULL(art.id,0) = 0 then '0' else '1' end tagCollect,
osd.ord_status as orderStatus from vm_order_sensor_devices osd left join vm_iot_device_t m on m.device_code = osd.device_code and m.category_code = 1 left join sys_area pro on pro.area_code = m.province_id left join sys_area city on city.area_code = m.city_id left join sys_area county on county.area_code = m.county_id left join sys_area town on town.area_code = m.town_code left join vm_tenant_iot_device_rel_t dr on dr.device_code = m.device_code and dr.tenant_id = osd.tenant_id and dr.delete_flag = '0' and dr.industry_code = osd.industry_code left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '8' AND dct.user_id = #{param.userId}
LEFT JOIN vm_organ_device_rel_t vod on vod.device_code = osd.device_code and osd.tenant_id = vod.tenant_id and vod.device_type = 10 and vod.delete_flag = '0'
LEFT JOIN vm_ar_tags_tree_user_rel art on art.coll_obj_code = m.device_code and art.coll_obj_type = '8' and art.user_id = #{param.userId}
where osd.delete_flag= '0' and m.delete_flag= '0' and osd.category_code = 1 and osd.tenant_id =#{param.tenantId}
and vod.dept_id in
#{id}
and dct.user_device_coll_id IS NOT NULL
and m.device_status != 2
and art.coll_obj_code IS NOT NULL
AND m.province_id = #{param.provinceId}
AND m.city_id = #{param.cityId}
AND m.county_id = #{param.countyId}
AND m.town_code = #{param.townCode}
and m.device_code like CONCAT('%', #{param.deviceCode}, '%')
and m.device_code in
#{item}
and m.device_status = #{param.deviceStatus}
and m.device_status in
#{status}
and m.device_type in
#{type}
and m.model_code = #{param.modelCode}
and osd.ord_status in (0, 1, 2)
and osd.ord_status = #{param.orderStatus}
${param.dataScope} order by m.province_id, m.city_id, m.county_id,m.device_code ) dt
dt.device_alias like CONCAT('%', #{param.deviceName}, '%')

select distinct m.device_code,m.device_status,m.device_name,m.longitude, m.latitude, c.channel_code, c.channel_name, m.province_id, m.city_id,m.county_id, pro.area_name as provinceName,city.area_name as cityName, county.area_name as countyName,m.device_code as code,m.device_name as name, '1' as prolevel,'2' as citylevel,'3' as countrylevel from vm_order_devices osd left join vm_device_info_t m on m.device_code = osd.device_code left join sys_area pro on pro.area_code = m.province_id left join sys_area city on city.area_code = m.city_id left join sys_area county on county.area_code = m.county_id left join vm_channel_info_t c on m.device_code = c.device_code
LEFT JOIN vm_organ_device_rel_t vod on vod.device_code = osd.device_code and osd.tenant_id = vod.tenant_id and vod.device_type = 4 and vod.delete_flag = '0'
where osd.delete_flag= '0' and m.delete_flag= '0' and m.province_id is not null and osd.ord_status in (0, 1, 2)
and osd.tenant_id = #{param.tenantId}
and osd.tenant_id in
#{item}
and m.access_node = #{platformCode}
${param.dataScope} order by m.province_id, m.city_id, m.county_id,m.device_code,c.channel_code

select m.device_code, m.device_name, c.channel_code, c.channel_name, m.province_id, m.city_id, m.county_id, pro.area_name as provinceName,city.area_name as cityName, county.area_name as countyName from vm_order_devices osd left join vm_device_info_t m on m.device_code = osd.device_code left join sys_area pro on pro.area_code = m.province_id left join sys_area city on city.area_code = m.city_id left join sys_area county on county.area_code = m.county_id left join vm_channel_info_t c on m.device_code = c.device_code
LEFT JOIN vm_organ_device_rel_t vod on vod.device_code = osd.device_code and osd.tenant_id = vod.tenant_id and vod.device_type = 4 and vod.delete_flag = '0'
where osd.delete_flag= '0' and m.delete_flag= '0' and m.province_id is not null and osd.ord_status in (0, 1, 2)
and osd.tenant_id = #{param.tenantId}
and osd.tenant_id in
#{item}
and m.access_node = #{platformCode}
order by m.province_id, m.city_id, m.county_id,m.device_code,c.channel_code

select DISTINCT od.device_code, ( case when length(IFNULL(ten.device_name, '')) = 0 then m.device_name else ten.device_name end ) device_name, m.longitude, m.latitude, m.device_status from vm_order_sensor_devices od left join vm_iot_device_t m on m.device_code = od.device_code left JOIN vm_tenant_iot_device_rel_t ten on ten.device_code = od.device_code and ten.tenant_id = od.tenant_id and ten.delete_flag='0' and ten.industry_code = od.industry_code where od.delete_flag = '0' and m.delete_flag = '0' and od.category_code = 2 and od.ord_status in (0, 1, 2) and od.tenant_id =#{param.tenantId}
and m.device_type in
