AND t.dept_id = #{deptId}
${dataScope}

SELECT DISTINCT CASE WHEN t1.device_type IS NULL THEN '' ELSE t1.device_type END AS deviceType, t1.device_code AS deviceCode, t1.device_name AS deviceName, t1.device_status AS deviceStatus, t1.longitude, t1.latitude, t1.location, t1.height, t1.province_id AS provinceId, t1.city_id AS cityId, t1.county_id AS countyId, t1.town_code AS townCode, vdi.device_code AS cameraCode, vdi.device_name AS cameraName, vdi.device_status AS cameraStatus, vdi.longitude AS cameraLongitude, vdi.latitude AS cameraLatitude, vdi.location AS cameraLocation, vic.channel_code AS channelCode, ca.channel_name AS channelName FROM vm_order_sensor_devices c INNER JOIN vm_iot_device_t t1 ON c.device_code = t1.device_code LEFT JOIN vm_tenant_iot_device_conf_t vit ON vit.device_code = c.device_code and vit.tenant_id = c.tenant_id and vit.industry_code = c.industry_code LEFT JOIN vm_tenant_iot_conf_rel_t vic ON vit.iot_device_conf_id = vic.iot_device_conf_id LEFT JOIN vm_device_info_t vdi ON vdi.device_code = vic.device_code LEFT JOIN vm_channel_info_t ca ON ca.channel_code = vic.channel_code WHERE c.category_code = '2' AND c.ord_status IN ( 0, 1, 2 ) AND t1.delete_flag = '0'
and t1.device_type = #{deviceType}
and t1.province_id = #{provinceId}
and t1.city_id = #{cityId}
and t1.county_id = #{countyId}
and t1.town_code = #{townCode}
${dataScope}

select o.device_code
from vm_order_sensor_devices o
inner join vm_sensor_monitor_status s on o.device_code = s.device_code
inner join vm_sensor_monitor_config c on c.monitor_code = s.monitor_code
where o.ord_status in (0,1,2) and o.category_code = 2

    and o.device_code in

        #{item}



    and c.monitor_code = #{param.monitorCode}

${param.dataScope}
group by o.device_code

select t.device_code, t.device_name as name, t.location, ST_Distance_Sphere( ST_GeomFromText(CONCAT('POINT(',#{param.longitude},' ',#{param.latitude},')')), ST_GeomFromText(CONCAT('POINT(',t.longitude,' ',t.latitude,')')) ) as distance, t.longitude, t.latitude, t.w_zone, t.height, t.device_type, t.model_code, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_model_type' AND DICT_VALUE = t.device_type limit 1) deviceTypeName, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_mfgr_code' AND DICT_VALUE = t.model_code limit 1) modelName, t.device_status from vm_iot_device_t t where t.delete_flag = '0' and t.device_status != 2 and t.category_code = 2
and ST_Distance_Sphere( ST_GeomFromText(CONCAT('POINT(',#{param.longitude},' ',#{param.latitude},')')), ST_GeomFromText(CONCAT('POINT(',t.longitude,' ',t.latitude,')')) ) <= #{param.radius}
AND t.device_type IN
#{item}
group by t.device_code order by distance asc, t.device_code

select s.device_code, s.sensor_code, s.monitor_code, s.status monitorStatus, c.monitor_name, c.monitor_units from vm_sensor_monitor_status s inner join vm_sensor_monitor_config c on s.monitor_code = c.monitor_code where s.delete_flag = '0' and c.delete_flag = '0' and s.device_code in
#{item}
and s.status = #{param.monitorStatus}
order by s.id

select type_code, type_name from vm_sensor_device_type where type_code in
#{item}
and delete_flag = 0

select distinct s.sensor_code, s.monitor_code, c.monitor_name, c.monitor_units from vm_sensor_monitor_status s inner join vm_sensor_monitor_config c on s.monitor_code = c.monitor_code
and s.device_code in
#{id}
and s.device_code = #{deviceCode}
and s.status = 1 and s.delete_flag = '0' and c.delete_flag = '0'

SELECT DISTINCT m.iot_device_id, od.device_code as deviceCode, ( case when length(IFNULL(ten.device_name, '')) = 0 then m.device_name else ten.device_name end ) device_name, m.device_status, m.device_type as deviceType, m.category_code, od.ord_status as orderStatus, (CASE WHEN od.ord_status in ('0','1','2') THEN '有效' WHEN od.ord_status = '3' THEN '退订' WHEN od.ord_status = '4' THEN '失效' END) orderStatusName, m.longitude, m.latitude, m.location, m.height, m.model_code, od.tenant_id as tenantId FROM vm_order_sensor_devices od LEFT JOIN vm_iot_device_t m on m.device_code = od.device_code and m.category_code = #{param.categoryCode} LEFT JOIN vm_tenant_iot_device_rel_t ten on ten.device_code = od.device_code and ten.tenant_id = od.tenant_id and ten.delete_flag='0' and ten.industry_code = od.industry_code where od.delete_flag = '0' and m.delete_flag = '0' and od.category_code = #{param.categoryCode}
and m.device_code like CONCAT('%', #{param.deviceCode}, '%')
and od.device_code in
#{deviceCode}
and od.ord_status in (0, 1, 2)
and od.ord_status = #{param.orderStatus}
${param.dataScope} GROUP BY od.tenant_id, od.industry_code, od.device_code

SELECT DISTINCT m.iot_device_id, od.device_code as deviceCode, ( case when length(IFNULL(ten.device_name, '')) = 0 then m.device_name else ten.device_name end ) device_name, m.device_status, (CASE WHEN m.device_status = '0' THEN '在线' WHEN m.device_status = '1' THEN '离线' END) deviceStatusName, m.device_type as deviceType, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_model_type' AND DICT_VALUE = m.device_type limit 1) deviceTypeName, m.category_code, od.ord_status as orderStatus, (CASE WHEN od.ord_status in ('0','1','2') THEN '有效' WHEN od.ord_status = '3' THEN '退订' WHEN od.ord_status = '4' THEN '失效' END) orderStatusName, m.longitude, m.latitude, m.location, m.height, m.w_zone as wZone, m.model_code, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, od.tenant_id as tenantId, pro.area_name as provinceName, pro.area_code as province_id, city.area_name as cityName, city.area_code as city_id, county.area_name as countyName, county.area_code as county_id, town.area_code as town_code, town.area_name as town_name FROM vm_order_sensor_devices od LEFT JOIN vm_iot_device_t m on m.device_code = od.device_code and m.category_code = #{param.categoryCode} LEFT JOIN vm_tenant_iot_device_rel_t ten on ten.device_code = od.device_code and ten.tenant_id = od.tenant_id and ten.delete_flag='0' and ten.industry_code = od.industry_code LEFT JOIN sys_area pro on pro.area_code = m.province_id LEFT JOIN sys_area city on city.area_code = m.city_id LEFT JOIN sys_area county on county.area_code = m.county_id LEFT JOIN sys_area town on town.area_code = m.town_code where od.delete_flag = '0' and m.delete_flag = '0' and od.ord_status in (0, 1, 2) and od.category_code = #{param.categoryCode} and od.tenant_id =#{param.tenantId}
AND m.province_id = #{param.provinceId}
AND m.city_id = #{param.cityId}
AND m.county_id = #{param.countyId}
AND m.town_code = #{param.townCode}
and m.device_code like CONCAT('%', #{param.deviceCode}, '%')
and m.device_status = #{param.deviceStatus}
and m.device_type = #{param.deviceType}
and m.device_type in
#{deviceType}
and m.device_type in
#{deviceType}
and m.device_type in
#{deviceType}
${param.dataScope} GROUP BY od.tenant_id, od.industry_code, od.device_code order by pro.area_code, city.area_code, county.area_code,od.device_code

select DISTINCT dt.site_code, dt.longitude, dt.latitude from ( select DISTINCT m.site_code, m.longitude, m.latitude, m.location, m.device_code, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end ) as device_name, m.province_id, m.city_id, m.county_id, m.town_code, m.height, m.device_status, m.model_code, m.device_period, m.w_zone, m.par_angle, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_model_type' AND DICT_VALUE = m.device_type limit 1) deviceTypeName, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, m.device_model_code, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor from vm_order_sensor_devices osd left join vm_iot_device_t m on osd.device_code = m.device_code and m.category_code = #{param.categoryCode} and m.delete_flag = 0 left join vm_tenant_iot_device_rel_t dr on dr.device_code = m.device_code and dr.tenant_id = osd.tenant_id and dr.delete_flag = '0' and dr.industry_code = osd.industry_code left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '7' AND dct.user_id = #{param.userId} where osd.delete_flag = 0 and osd.ord_status in (0,1,2) and osd.category_code = #{param.categoryCode} and m.delete_flag= '0' and m.device_status != 2
AND m.province_id = #{param.provinceId}
AND m.city_id = #{param.cityId}
AND m.county_id = #{param.countyId}
AND m.town_code = #{param.townCode}
and m.device_type in
#{type}
and m.site_code in
#{siteCode}
${param.dataScope} group by m.site_code, m.device_code) dt where 1 = 1
and (dt.device_name like concat('%',#{param.keyWords},'%') or dt.device_code like concat('%',#{param.keyWords},'%'))

select * from (select DISTINCT m.site_code, m.longitude, m.latitude, m.location, m.device_code, (case when length(IFNULL(dr.device_name, '')) = 0 then m.device_name else dr.device_name end ) as device_name, m.province_id, m.city_id, m.county_id, m.town_code, m.height, m.device_status, m.model_code, m.device_period, m.w_zone, m.par_angle, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_model_type' AND DICT_VALUE = m.device_type limit 1) deviceTypeName, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, m.device_model_code, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor from vm_order_sensor_devices osd left join vm_iot_device_t m on osd.device_code = m.device_code and m.category_code = #{param.categoryCode} and m.delete_flag = 0 left join vm_tenant_iot_device_rel_t dr on dr.device_code = m.device_code and dr.tenant_id = osd.tenant_id and dr.delete_flag = '0' and dr.industry_code = osd.industry_code left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '7' AND dct.user_id = #{param.userId} where osd.delete_flag = 0 and osd.ord_status in (0,1,2) and osd.category_code = #{param.categoryCode} and m.delete_flag= '0' and m.device_status != 2
AND m.province_id = #{param.provinceId}
AND m.city_id = #{param.cityId}
AND m.county_id = #{param.countyId}
AND m.town_code = #{param.townCode}
and m.device_type in
#{type}
and m.site_code in
#{siteCode}
${param.dataScope} group by m.site_code, m.device_code) dt where 1 = 1
and (dt.device_name like concat('%',#{param.keyWords},'%') or dt.device_code like concat('%',#{param.keyWords},'%'))
